    23	const CLAMP = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
    24	const ease = Easing.bezier(...motion.ease);
    25	
    26	/** Scene-local motion. Every helper has finished by `settle` frames, before the middle of the scene. */
    27	export function useMotion() {
    28	  const frame = useCurrentFrame();
    29	  const { fps, durationInFrames } = useVideoConfig();
    30	  const settle = Math.max(1, durationInFrames * motion.settleBy);
    31	  const length = Math.max(1, Math.min(motion.enterSec * fps, settle));
    32	  const from = (start: number, frames: number) => interpolate(frame, [start, start + Math.max(1, frames)], [0, 1], { ...CLAMP, easing: ease });
    33	  return {
    34	    frame,
    35	    fps,
    36	    settle,
    37	    /** Entrance of element `order` in a quick stagger from the top of the scene. */
    38	    enter: (order = 0) => from(Math.min(order * motion.staggerSec * fps, settle - length), length),
    39	    /** Entrance of item `index` of `count`, the starts spread across the settle window. */
    40	    reveal: (index: number, count: number) => from(((settle - length) * index) / Math.max(1, count - 1), length),
    41	    /** Linear progress through slot `index` when the settle window is cut into `count` equal slots. */
    42	    slot: (index: number, count: number) => interpolate(frame, [(settle * index) / count, Math.max((settle * index) / count + 1, (settle * (index + 1)) / count)], [0, 1], CLAMP),
    43	    /** Eased progress between two shares of the settle window. */
    44	    span: (start: number, end: number) => from(settle * start, settle * (end - start)),
    45	  };
    46	}
