     1	import React from 'react';
     2	import { interpolate } from 'remotion';
     3	import { theme } from '../../theme';
     4	import { LIMITS, clampEnd, tailLines } from '../text';
     5	import { Frame, Mark, Panel, useContentBox, useMotion, type SceneOf } from '../ui';
     6	
     7	const { color, font, size, leading, space, advance } = theme;
     8	
     9	const MAX_STEPS = 4;
    10	const CLAMP = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
    11	
    12	export const Terminal: React.FC<{ scene: SceneOf<'terminal'> }> = ({ scene }) => {
    13	  const m = useMotion();
    14	  const box = useContentBox();
    15	  const steps = scene.steps.slice(0, MAX_STEPS);
    16	
    17	  // Whole rows and columns of the code face that fit the panel; nothing is left to be cut off by overflow.
    18	  const rowHeight = size.code * leading.code;
    19	  const rows = Math.floor((box.height - 2 * space.lg - (steps.length - 1) * space.md) / rowHeight);
    20	  const cols = Math.floor((box.width - 2 * space.lg) / (size.code * advance.mono));
    21	  const outputRows = Math.max(0, Math.floor(rows / steps.length) - 1);
    22	  const markCols = Math.ceil((size.icon + space.md) / (size.code * advance.mono));
    23	
    24	  return (
    25	    <Frame label="Terminal">
    26	      <Panel style={{ flex: 1, padding: space.lg, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: space.md, fontFamily: font.mono, fontSize: size.code, lineHeight: leading.code }}>
    27	        {steps.map((step, i) => {
    28	          // Each step owns one slot of the settle window: the command is typed, its output lands, then the mark.
    29	          const p = m.slot(i, steps.length);
    30	          const command = Array.from(clampEnd(step.command.replace(/\s+/g, ' ').trim(), Math.min(LIMITS.command, cols - 2 - markCols)));
    31	          const typed = Math.floor(interpolate(p, [0, 0.5], [0, command.length], CLAMP));
    32	          const landed = interpolate(p, [0.5, 0.75], [0, 1], CLAMP);
    33	          const marked = interpolate(p, [0.75, 1], [0, 1], CLAMP);
    34	          const output = tailLines(clampEnd(step.output, LIMITS.output), outputRows, cols);
    35	          return (
    36	            <div key={i} style={{ opacity: interpolate(p, [0, 0.05], [0, 1], CLAMP) }}>
    37	              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', height: rowHeight }}>
    38	                <div style={{ whiteSpace: 'pre' }}>
    39	                  <span style={{ color: color.accent }}>$ </span>
    40	                  <span>{command.slice(0, typed).join('')}</span>
    41	                </div>
    42	                <Mark ok={step.ok} progress={marked} />
    43	              </div>
    44	              <div style={{ opacity: landed, color: color.muted, whiteSpace: 'pre' }}>
    45	                {output.skipped > 0 && outputRows > 0 ? <div style={{ height: rowHeight, color: color.faint }}>{`… ${output.skipped} earlier lines`}</div> : null}
    46	                {output.lines.map((line, j) => (
    47	                  <div key={j} style={{ height: rowHeight }}>{line}</div>
    48	                ))}
    49	              </div>
    50	            </div>
    51	          );
    52	        })}
    53	      </Panel>
    54	    </Frame>
    55	  );
    56	};
