121	    29	export function buildTimeline(sb: Storyboard, timings: LineTiming[], fps: number = FPS): Timeline {
122	    30	  const title = sb.scenes[0];
123	    31	  const end = sb.scenes.at(-1);
124	    32	  if (title?.type !== 'title') throw new Error('storyboard must start with a title scene');
125	    33	  if (sb.scenes.length < 2 || end?.type !== 'end') throw new Error('storyboard must finish with an end scene');
126	    34	  const spoken = sb.scenes.slice(1, -1);
127	    35	  spoken.forEach((scene, i) => {
128	    36	    if (scene.type === 'title' || scene.type === 'end') throw new Error(`scene ${i + 1} (${scene.type}) cannot sit between spoken scenes`);
