140	    48	    const firstLine = lines.get(scene.lines[0]!.id)!;
141	    49	    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(firstLine.startSec)));
142	    50	  }
143	    51	  const lastScene = spoken.at(-1);
144	    52	  if (lastScene) {
145	    53	    const lastLine = lines.get(lastScene.lines.at(-1)!.id)!;
146	    54	    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(lastLine.endSec + TAIL_SEC)));
147	    55	  }
148	    56	
149	    57	  const scenes = [
150	    58	    { sceneId: title.id, startFrame: 0, durationInFrames: audioStartFrame },
151	    59	    ...spoken.map((scene, i) => ({ sceneId: scene.id, startFrame: cuts[i]!, durationInFrames: cuts[i + 1]! - cuts[i]! })),
152	    60	    { sceneId: end.id, startFrame: cuts.at(-1)!, durationInFrames: frames(END_SEC) },
153	    61	  ];
