642	   108	const WRAP_FILL = 0.85;   // share of a wrapped block that holds glyphs; the rest is ragged line ends
643	   109	const LINE_FILL = 0.92;   // margin for glyphs wider than the average advance
644	   110	
645	   111	/** Largest font size, in whole pixels, at which `chars` glyphs (see `textUnits`) wrap inside `box`. `advance` is the mean glyph width in em. */
646	   112	export function fitSize(chars: number, box: { width: number; height: number }, type: { max: number; min: number; advance: number; leading: number }): number {
647	   113	  for (let size = type.max; size > type.min; size--) {
648	   114	    const cols = Math.floor(box.width / (size * type.advance));
649	   115	    const rows = Math.floor(box.height / (size * type.leading));
650	   116	    if (cols * rows * WRAP_FILL >= chars) return size;
651	   117	  }
652	   118	  return type.min;
653	   119	}
654	   120	
655	   121	/** Largest font size at which `chars` characters stay on one line of `width`. */
656	   122	export function fitLine(chars: number, width: number, type: { max: number; min: number; advance: number }): number {
657	   123	  const size = Math.floor((width * LINE_FILL) / (Math.max(1, chars) * type.advance));
658	   124	  return Math.max(type.min, Math.min(type.max, size));
